# Bài tập 
c = int(input())
matrix = []
for _ in range(c):
    row = list(map(int, input().split()))
    matrix.append(row)
p = int(input())
s1 = 0
s2 = 0
for i in range(c):
    for j in range(c):
        if i < j:
            s1 += matrix[i][j]
        if i > j:
            s2 += matrix[i][j]

s = abs(s1 - s2)

if s <= p:
    print('YES')
else:
    print('NO')
print(s)

